package com.receiptledger.v1.review;

import android.app.*;import android.content.Context;import android.text.InputType;import android.view.*;import android.widget.*;import com.receiptledger.v1.R;import com.receiptledger.v1.persistence.*;import java.util.*;

public final class ReceiptReviewDialog {
    public interface Callback{void onApplied(ReceiptRecord reviewed);}
    private ReceiptReviewDialog(){}
    public static void show(Activity activity,ReceiptRecord base,Callback callback){ReceiptReviewEngine engine=new ReceiptReviewEngine();int pad=dp(activity,12);LinearLayout form=new LinearLayout(activity);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(pad,pad,pad,pad);TextView help=text(activity,activity.getString(R.string.review_help));form.addView(help);EditText date=field(activity,"날짜 YYYY-MM-DD",base.purchaseDate,false);EditText total=field(activity,"영수증 합계",fmt(base.printedTotal),true);EditText discount=field(activity,"할인 합계(할인은 음수)",fmt(base.discountSum),true);form.addView(date);form.addView(total);form.addView(discount);List<RowFields> rows=new ArrayList<>();for(int i=0;i<base.items.size();i++){PersistedItem item=base.items.get(i);TextView label=text(activity,"상품 "+(i+1)+" · "+item.resolution);label.setPadding(0,pad,0,0);form.addView(label);EditText name=field(activity,"상품명",item.name,false),q=field(activity,"수량",fmt(item.quantity),true),unit=field(activity,"단가",fmt(item.unitPrice),true),amount=field(activity,"행금액",fmt(item.lineAmount),true);form.addView(name);LinearLayout nums=new LinearLayout(activity);nums.setOrientation(LinearLayout.HORIZONTAL);nums.addView(q,new LinearLayout.LayoutParams(0,-2,1));nums.addView(unit,new LinearLayout.LayoutParams(0,-2,1));nums.addView(amount,new LinearLayout.LayoutParams(0,-2,1));form.addView(nums);rows.add(new RowFields(name,q,unit,amount));}ScrollView scroll=new ScrollView(activity);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(R.string.review_title).setView(scroll).setNegativeButton(android.R.string.cancel,null).setPositiveButton(R.string.apply_review,null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String d=ReviewInputParser.nullableDate(date.getText().toString());Long t=ReviewInputParser.nullableMoney(total.getText().toString()),disc=ReviewInputParser.nullableMoney(discount.getText().toString());List<ReviewItemInput> edits=new ArrayList<>();for(RowFields r:rows)edits.add(new ReviewItemInput(r.name.getText().toString(),ReviewInputParser.nullableQuantity(r.quantity.getText().toString()),ReviewInputParser.nullableMoney(r.unit.getText().toString()),ReviewInputParser.nullableMoney(r.amount.getText().toString())));ReceiptRecord reviewed=engine.apply(base,d,t,disc,edits);callback.onApplied(reviewed);dialog.dismiss();}catch(IllegalArgumentException e){Toast.makeText(activity,e.getMessage(),Toast.LENGTH_LONG).show();}}));dialog.show();}
    private static EditText field(Context c,String hint,Object value,boolean number){EditText e=new EditText(c);e.setHint(hint);e.setSingleLine(true);if(value!=null)e.setText(String.valueOf(value));if(number)e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);return e;}private static TextView text(Context c,String s){TextView t=new TextView(c);t.setText(s);return t;}private static String fmt(Object v){return v==null?"":String.valueOf(v);}private static int dp(Context c,int v){return Math.round(v*c.getResources().getDisplayMetrics().density);}private static final class RowFields{final EditText name,quantity,unit,amount;RowFields(EditText n,EditText q,EditText u,EditText a){name=n;quantity=q;unit=u;amount=a;}}
}
